// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address actor, address newLog) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        c.Initialized();
        vm.prank(actor);
        bool ok;
        try c.SetLogFile(newLog) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false, "SetLogFile must revert after initialization");
    }
}
